import type { ReactElement } from "react";
import { describeQuery, parseSearchQuery } from "./query-syntax";
import { SearchResults } from "./search-results";

export type SearchDialogProps = {
  open: boolean;
  orgId: OrgId;
  flags: FeatureFlagSnapshot;
  onClose: () => void;
  onSearch: (input: SearchQueryInput) => Promise<ActionResult<SearchHit[]>>;
};

const SEARCH_PAGE_SIZE = 20;

export function SearchDialog(props: SearchDialogProps): ReactElement | null {
  const { open, orgId, flags, onClose, onSearch } = props;

  const [raw, setRaw] = useState("");
  // Results are stored together with the query that produced them, so
  // "still searching" is derived rather than a second piece of state that
  // could disagree with the first.
  const [results, setResults] = useState<{
    query: string;
    hits: readonly SearchHit[];
  }>({ query: "", hits: [] });

  const debounced = useDebouncedValue(raw);
  const advanced =
    flags.advanced_search === true ||
    isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });
  const parsed = parseSearchQuery(debounced, advanced);

  const query = parsed.text;
  const pending = query.length > 0 && results.query !== query;

  useEffect(() => {
    if (!open || query.length === 0) return;

    let cancelled = false;

    void onSearch({
      orgId,
      q: query,
      kinds: [...parsed.kinds],
      ...(parsed.projectId !== null ? { projectId: parsed.projectId } : {}),
      limit: SEARCH_PAGE_SIZE,
    }).then((result) => {
      if (cancelled) return;
      setResults({ query, hits: result.ok ? result.data : [] });
    });

    return () => {
      cancelled = true;
    };
    // `parsed` is derived from the debounced string; depending on its parts
    // keeps the effect from re-firing on every keystroke.
  }, [open, orgId, onSearch, query, parsed.kinds, parsed.projectId]);

  if (!open) return null;

  return (
    <Dialog
      open={open}
      title="Search"
      description={
        advanced
          ? "Use kind:issue or project:<id> to narrow the search."
          : undefined
      }
      onClose={onClose}
    >
      <Input
        name="q"
        type="search"
        value={raw}
        placeholder={advanced ? "kind:comment deploy failed" : "Search…"}
        onChange={setRaw}
      />

      {advanced && debounced.length > 0 ? (
        <p className="mt-1 text-xs text-neutral-500">{describeQuery(parsed)}</p>
      ) : null}

      <div className="mt-3">
        {pending ? (
          <Spinner size="sm" label="Searching" />
        ) : (
          <SearchResults
            hits={results.query === query ? results.hits : []}
            query={query}
            onSelect={() => onClose()}
          />
        )}
      </div>
    </Dialog>
  );
}

import {
  FEATURE_FLAG_DEFINITIONS,
  FEATURE_FLAG_KEYS,
} from "@/config/feature-flags";
import { planAtLeast } from "@/config/plan-limits";
import { ROLE_RANK } from "@/types/member";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";

/**
 * Feature-flag evaluation, shared verbatim by server and client.
 *
 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
 * directly; the dashboard layout serialises `snapshotFlags()` into the client
 * provider so `useFeatureFlag()` answers the same way without a round trip.
 * Both sides must agree — never re-implement a strategy at a call site.
 */
export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
  const definition = FEATURE_FLAG_DEFINITIONS[flag];
  if (!definition) return false;

  if (definition.overridable && ctx.overrides?.includes(flag)) {
    return true;
  }

  const strategy = definition.strategy;
  switch (strategy.kind) {
    case "off":
      return false;
    case "on":
      return true;
    case "plan":
      return planAtLeast(ctx.plan, strategy.minPlan);
    case "role":
      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    case "percentage":
      return bucketOf(flag, ctx) < strategy.percent;
    default:
      return false;
  }
}

/** Evaluates every flag at once, for handoff to the client provider. */
export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
  const snapshot = {} as Record<FeatureFlagKey, boolean>;
  for (const key of FEATURE_FLAG_KEYS) {
    snapshot[key] = isEnabled(key, ctx);
  }
  return snapshot;
}

/** Throwing guard for server actions gated behind a flag. */
export class FeatureDisabledError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: FeatureFlagKey) {
    super(`Feature "${flag}" is not enabled for this organization.`);
    this.name = "FeatureDisabledError";
  }
}

export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
  if (!isEnabled(flag, ctx)) {
    throw new FeatureDisabledError(flag);
  }
}

/**
 * Deterministic 0–99 bucket for percentage rollouts. Stable per
 * (flag, org, user) so a viewer never sees the feature flicker.
 */
function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
  let hash = 2_166_136_261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash) % 100;
}
import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";
import type { IssueStatus, IssuePriority } from "./issue";
import type { Role } from "./member";
import type { PlanId, LimitedResource } from "./billing";
import type { FeatureFlagKey } from "./feature-flag";

/** Fields present on every event payload; the bus stamps them on `emit`. */
export interface EventEnvelope {
  readonly orgId: OrgId;
  readonly actorId: UserId | null;
  readonly occurredAt: IsoTimestamp;
}

/**
 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 * only way to introduce one — services, jobs and the webhook dispatcher all
 * derive their handler signatures from it.
 */
export interface TaskflowEventMap {
  "project.created": EventEnvelope & {
    projectId: ProjectId;
    name: string;
    slug: string;
  };
  "project.archived": EventEnvelope & {
    projectId: ProjectId;
    issuesArchived: number;
  };
  "project.restored": EventEnvelope & { projectId: ProjectId };
  "issue.created": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    title: string;
    assigneeId: UserId | null;
    priority: IssuePriority;
  };
  "issue.updated": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    changedFields: readonly string[];
  };
  "issue.status_changed": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    from: IssueStatus;
    to: IssueStatus;
  };
  "issue.assigned": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    previousAssigneeId: UserId | null;
    assigneeId: UserId;
  };
  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
  "issue.overdue": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    dueAt: IsoTimestamp;
    assigneeId: UserId | null;
  };
  "comment.created": EventEnvelope & {
    commentId: CommentId;
    issueId: IssueId;
    mentionedUserIds: readonly UserId[];
  };
  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
  "member.invited": EventEnvelope & { email: string; role: Role };
  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
  "member.role_changed": EventEnvelope & {
    memberId: MemberId;
    from: Role;
    to: Role;
  };
  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
  "billing.limit_exceeded": EventEnvelope & {
    resource: LimitedResource;
    limit: number;
    used: number;
  };
  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
  "search.reindex_requested": EventEnvelope & {
    subjectKind: "issue" | "comment" | "project";
    subjectId: string;
  };
  "webhook.delivery_requested": EventEnvelope & {
    eventType: string;
    payload: Readonly<Record<string, unknown>>;
  };
}

export type TaskflowEventType = keyof TaskflowEventMap;

export type TaskflowEventPayload<K extends TaskflowEventType> =
  TaskflowEventMap[K];

/** A handler registered with `subscribe()`. May be async; errors are isolated. */
export type EventHandler<K extends TaskflowEventType> = (
  payload: TaskflowEventPayload<K>,
) => void | Promise<void>;

/** Returned by `subscribe()`; calling it removes the handler. */
export type Unsubscribe = () => void;
import { z } from "zod";
import { orgIdSchema, pageRequestSchema, projectIdSchema } from "./common";

export const searchSubjectKindSchema = z.enum(["issue", "comment", "project"]);

export const searchQuerySchema = z
  .object({
    orgId: orgIdSchema,
    q: z.string().min(1, "type something to search").max(200),
    kinds: z.array(searchSubjectKindSchema).default(["issue"]),
    projectId: projectIdSchema.optional(),
  })
  .extend(pageRequestSchema.shape);

export const reindexRequestSchema = z.object({
  orgId: orgIdSchema,
  subjectKind: searchSubjectKindSchema,
  subjectId: z.string().min(1),
});

export type SearchQueryInput = z.infer<typeof searchQuerySchema>;
export type ReindexRequestInput = z.infer<typeof reindexRequestSchema>;

/**
 * Comment rows, soft deleted so a deleted comment keeps its place in the thread.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, asc, count, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { comments, getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toComment, toUser } from "./_mappers";
import type {
  CreateCommentInput,
  ListCommentsInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type {
  Comment,
  CommentThreadNode,
  CommentWithAuthor,
} from "@/types/comment";
import type { CommentId, IssueId, OrgId, Page, UserId } from "@/types/common";

export async function findCommentById(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment | null> {
  const row = getDb()
    .select()
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .get();
  return row ? toComment(row) : null;
}

export async function listComments(
  input: ListCommentsInput,
): Promise<Page<CommentWithAuthor>> {
  const db = getDb();
  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };

  const filters = compact(
    orgPredicate(comments.orgId, input.orgId),
    eq(comments.issueId, input.issueId),
    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,
  );

  const total = db
    .select({ value: count() })
    .from(comments)
    .where(and(...filters))
    .get();

  const rows = db
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(comments.createdAt), desc(comments.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),
    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),
  );
}

/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. Archived comments are kept so a reply
 * chain never loses its anchor — the UI renders them as "deleted".
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
        isNull(comments.archivedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertComment(
  input: CreateCommentInput,
  authorId: UserId,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toComment(row);
}

/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */
export async function updateComment(
  input: UpdateCommentInput,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        eq(comments.id, input.commentId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${input.commentId} not found`);
  return toComment(row);
}

export async function archiveComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment> {
  const row = getDb()
    .update(comments)
    .set(archivePatch())
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${commentId} not found`);
  return toComment(row);
}
